// ───────────────────────── 막대 윤곽 · 자세 ─────────────────────────

/** 막대 로컬(u, y) 위쪽 윤곽 — 이 m = −12 … 6: 선 면 꼭대기 (0.12m, 1.27) → 선 면 바닥 (0.12m + 0.02127, 1.20), 비탈은 다음 꼭대기까지 곧게 */
const BAR_TOP: V2[] = (() => {
  const top: V2[] = [
    [K.BAR[0], K.Y_ROOT],
    [-1.44, K.Y_ROOT]
  ];
  for (let m = -12; m <= 6; m++) {
    top.push([K.PITCH * m, K.Y_ROOT + K.TOOTH_H]);
    top.push([K.PITCH * m + K.FACE_DX, K.Y_ROOT]);
  }
  top.push([K.BAR[1], K.Y_ROOT]);
  return top;
})();

export function barOutline271(): V2[] {
  return [...BAR_TOP, [K.BAR[1], 1.08], [K.BAR[0], 1.08]];
}

/** 점 (px, py) 에서 선분 (ax, ay)-(bx, by) 까지 거리 */
function segDist(px: number, py: number, ax: number, ay: number, bx: number, by: number): number {
  const dx = bx - ax;
  const dy = by - ay;
  const L2 = dx * dx + dy * dy;
  const t = L2 > 0 ? Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / L2)) : 0;
  return Math.hypot(px - ax - t * dx, py - ay - t * dy);
}

/** 막대 위쪽 이 윤곽(세계, 막대 X 만큼 옮김)까지 (cx, cy) 의 거리 — 둘레 ±0.3 안 선분만 */
function toothDist(cx: number, cy: number, X: number): number {
  let best = Infinity;
  for (let i = 0; i + 1 < BAR_TOP.length; i++) {
    const a = BAR_TOP[i]!;
    const b = BAR_TOP[i + 1]!;
    const ax = a[0] + X;
    const bx = b[0] + X;
    if (Math.max(ax, bx) < cx - 0.3 || Math.min(ax, bx) > cx + 0.3) continue;
    const d = segDist(cx, cy, ax, a[1], bx, b[1]);
    if (d < best) best = d;
  }
  return best;
}

/** 밀 때 폴 끝 중심 높이 yc 에서의 폴 끝 x (핀 q, 폴 길이 L) */
function tipX(q: [number, number], L: number): number {
  return q[0] - Math.sqrt(L * L - (q[1] - K.YC) ** 2);
}

/** 폴이 걸려 내려앉는 각 γ(rad, 끝 중심 = q − L·(cos γ, sin γ)): 2° 에서 0.25° 씩 키우며 끝 원이 이 윤곽에 닿는 첫 각을 이분법으로 */
export function pawlGamma271(q: [number, number], L: number, X: number): number {
  const step = 0.25 * DEG;
  const dist = (g: number): number => toothDist(q[0] - L * Math.cos(g), q[1] - L * Math.sin(g), X);
  for (let g = 2 * DEG; g < 50 * DEG; g += step) {
    if (dist(g) < K.RT) {
      let lo = g - step;
      let hi = g;
      for (let i = 0; i < 50; i++) {
        const mid = (lo + hi) / 2;
        if (dist(mid) >= K.RT) lo = mid;
        else hi = mid;
      }
      return lo;
    }
  }
  return 50 * DEG;
}

export interface State271 {
  phase: 'feed1' | 'feed2' | 'reset';
  phi: number;
  X: number;
  q1: [number, number];
  q2: [number, number];
  gamma1: number;
  gamma2: number;
}

/** 지렛대 각 phi 에서 폴 핀 Q1·Q2 의 세계 위치 */
export function pins271(phi: number): { q1: [number, number]; q2: [number, number] } {
  return {
    q1: [K.P[0] + K.E1 * Math.cos(K.A1 + phi), K.P[1] + K.E1 * Math.sin(K.A1 + phi)],
    q2: [K.P[0] + K.E2 * Math.cos(K.A2 + phi), K.P[1] + K.E2 * Math.sin(K.A2 + phi)]
  };
}

export function state271(t: number): State271 {
  const tc = posMod(t, K.PERIOD);
  if (tc < 2 * K.T_SWING) {
    const phi = -K.AMP * Math.cos((2 * Math.PI * tc) / K.T_SWING);
    const { q1, q2 } = pins271(phi);
    const n = Math.floor(tc / K.T_SWING);
    const tau = tc - K.T_SWING * n;
    const a1 = pins271(-K.AMP).q1;
    const a2 = pins271(K.AMP).q2;
    let X: number;
    let phase: 'feed1' | 'feed2';
    if (tau <= K.T_SWING / 2) {
      X = -0.24 * n - (tipX(a1, K.L1) - tipX(q1, K.L1));
      phase = 'feed1';
    } else {
      X = -0.24 * n - 0.12 - (tipX(a2, K.L2) - tipX(q2, K.L2));
      phase = 'feed2';
    }
    return { phase, phi, X, q1, q2, gamma1: pawlGamma271(q1, K.L1, X), gamma2: pawlGamma271(q2, K.L2, X) };
  }
  const u = tc - 2 * K.T_SWING;
  const phi = -K.AMP;
  const { q1, q2 } = pins271(phi);
  const lam = u < 0.6 ? ss(u / 0.6) : u < 3.4 ? 1 : ss((4 - u) / 0.6);
  const X = -0.48 + 0.48 * ss((u - 0.6) / 2.8);
  return {
    phase: 'reset',
    phi,
    X,
    q1,
    q2,
    gamma1: K.G1_REF - (K.LIFT / K.L1) * lam,
    gamma2: K.G2_REF - (K.LIFT / K.L2) * lam
  };
}

// ───────────────────────── 부품 ─────────────────────────

/** 기운 선 면 톱니 막대. 로컬 u = 세계 x − X, 깊이 −0.09~0.09. userData.outline = 윤곽 */
export function ratchetBar271(): THREE.Mesh {
  const outline = barOutline271();
  const m = mesh(extrude(shapeFrom(outline), 0.18, 0.004), brass());
  m.userData.outline = outline;
  // 노란 띠: 앞면 왼쪽 끝 가까이(움직임이 보이게)
  m.add(meshAt(new THREE.BoxGeometry(0.06, 0.04, 0.004), paint(0xf2b619), -1.4, 1.14, 0.0925));
  return m;
}

const BODY: Record<1 | 2, { K: [number, number]; z0: number }> = {
  1: { K: [-1.73986, -0.44067], z0: -0.075 },
  2: { K: [-1.04446, -0.1592], z0: 0.015 }
};

/** 폴: 그룹 원점 = 핀 Q, 기준 자세(t = 0)의 점을 Q 에 대한 오프셋으로 둔다. rotation.z = γ − γref. 판 두께 0.05 */
export function pawl271(ref: 1 | 2): THREE.Group {
  const g = new THREE.Group();
  const out = ref === 1 ? PAWL1_OUT : PAWL2_OUT;
  const { K: Kn, z0 } = BODY[ref];
  const shape = shapeFrom(out);
  shape.holes.push(circlePath(0, 0, 0.017));
  const body = mesh(extrude(shape, 0.05, 0.003), steel());
  body.name = `pawl${ref}Body`;
  body.position.z = z0 + 0.025;
  g.add(body);
  // 색 띠: 위 폴은 노랑, 아래 폴은 빨강 — 몸 가운데
  const band = meshAt(new THREE.BoxGeometry(0.08, 0.02, 0.004), paint(ref === 1 ? 0xf2b619 : 0xd8362f), Kn[0] * 0.5, Kn[1] * 0.5, z0 + 0.052);
  band.rotation.z = Math.atan2(Kn[1], Kn[0]);
  g.add(band);
  g.userData.outline = out;
  return g;
}

/** 지렛대: 원점 P, 판 + 두 폴 핀(pinQ1·pinQ2) + 손잡이 끝 붉은 덮개 */
export function lever271(): THREE.Group {
  const g = new THREE.Group();
  const q1: V2 = [K.E1 * Math.cos(K.A1), K.E1 * Math.sin(K.A1)];
  const q2: V2 = [K.E2 * Math.cos(K.A2), K.E2 * Math.sin(K.A2)];
  const shape = shapeFrom(LEVER_OUT);
  shape.holes.push(circlePath(0, 0, 0.026), circlePath(q1[0], q1[1], 0.017), circlePath(q2[0], q2[1], 0.017));
  const plate = mesh(extrude(shape, 0.04, 0.004), darkSteel());
  plate.name = 'leverPlate';
  plate.position.z = -0.105;
  g.add(plate);
  // 손잡이 끝 붉은 덮개
  const cap = pinZ(0.046, -0.0848, -0.071, paint(0xd8362f), 0.004);
  cap.position.set(0.65 * Math.cos(25 * DEG), 0.65 * Math.sin(25 * DEG), 0);
  cap.name = 'leverCap';
  g.add(cap);
  // 폴 핀: 위 폴 앞면 −0.025 / 아래 폴 앞면 0.065 까지 + 머리(앞면과 0.002 띄움)
  const mkPin = (name: string, p: V2, zEnd: number): THREE.Group => {
    const pg = new THREE.Group();
    pg.name = name;
    pg.position.set(p[0], p[1], 0);
    pg.add(pinZ(0.016, -0.125, zEnd + 0.003, steel(), 0.002));
    pg.add(pinZ(0.026, zEnd + 0.002, zEnd + 0.014, steel(), 0.003));
    return pg;
  };
  g.add(mkPin('pinQ1', q1, -0.025), mkPin('pinQ2', q2, 0.065));
  return g;
}

/** 받침 틀: 윗보 + 발 둘 + 막대 옆 안내 띠 둘 */
export function bed271(): THREE.Group {
  const g = new THREE.Group();
  const iron = castIron();
  const beam = box(-1.2, 0.8, 0.9, 1.08, -0.2, 0.2, iron, 0.012, 0.01);
  beam.name = 'bedBeam';
  g.add(beam);
  for (const [x0, x1] of [
    [-0.95, -0.65],
    [0.15, 0.45]
  ] as [number, number][]) {
    const foot = box(x0, x1, 0.18, 0.9, -0.18, 0.18, iron, 0.01, 0.008);
    foot.name = 'bedFoot';
    g.add(foot);
  }
  for (const [z0, z1] of [
    [0.095, 0.13],
    [-0.13, -0.095]
  ] as [number, number][]) {
    const strip = box(-1.2, 0.8, 1.08, 1.16, z0, z1, steel(), 0.004, 0.003);
    strip.name = 'barGuide';
    g.add(strip);
  }
  return g;
}
